if grep -F 'Technical design limitations prevent ClamAV from scanning files greater than' "$root/etc/clamd.conf.sample" >/dev/null 2>&1; then
    echo 'large-file source guard failed: stale clamd.conf size limit documentation' >&2
    exit 1
fi

inventory_tmp=$(mktemp "${TMPDIR:-/tmp}/clamav-largefile-inventory.XXXXXX")
trap 'rm -f "$inventory_tmp"' EXIT HUP INT TERM
sh "$root/tools/largefile_inventory.sh" > "$inventory_tmp"
if ! cmp -s "$root/docs/largefile-inventory.tsv" "$inventory_tmp"; then
    echo 'large-file source guard failed: committed inventory is stale' >&2
    exit 1
fi

awk -F '\t' '
    NR == 1 { next }
    $2 ~ /^\.\// { exit 1 }
    seen[$0]++
    END {
        for (row in seen)
            if (seen[row] != 1)
                exit 2
    }
' "$root/docs/largefile-inventory.tsv"

sh "$root/tools/largefile_capability_manifest.sh"
sh "$root/tools/largefile_release_readiness_test.sh"

echo 'large-file source guards passed'
